## Error Handling Best Practices

### Client-Side Error Handling

#### 1. Use ApiError Class

The frontend `api.ts` provides a custom `ApiError` class:

```typescript
import { api, ApiError } from '@/services/api';

try {
  const result = await api.post('/api/ai/chat', { messages, model });
} catch (error) {
  if (error instanceof ApiError) {
    console.error(`API Error ${error.status}: ${error.message}`);

    switch (error.status) {
      case 400:
        // Handle validation errors
        break;
      case 401:
        // Redirect to login
        break;
      case 429:
        // Implement backoff and retry
        break;
      case 500:
        // Show generic error message
        break;
    }
  }
}
```

#### 2. Handle Rate Limits Gracefully

```typescript
async function makeRequestWithRetry(endpoint: string, data: any, maxRetries = 3) {
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await api.post(endpoint, data);
    } catch (error) {
      if (error instanceof ApiError && error.status === 429) {
        const retryAfter = extractRetryAfter(error.message) || Math.pow(2, attempt) * 1000;
        await sleep(retryAfter * 1000);
        continue;
      }
      throw error;
    }
  }
}
```

#### 3. Provide User-Friendly Messages

```typescript
function getUserFriendlyError(error: ApiError): string {
  switch (error.status) {
    case 400:
      return 'Please check your input and try again.';
    case 401:
      return 'Please log in to continue.';
    case 403:
      return 'You don\'t have permission to access this resource.';
    case 409:
      return 'An account with this email already exists.';
    case 429:
      return 'Too many requests. Please wait a moment and try again.';
    case 500:
    case 503:
      return 'Something went wrong. Please try again later.';
    default:
      return error.message || 'An unexpected error occurred.';
  }
}
```

### Server-Side Error Handling

#### 1. Never Expose Sensitive Information

```typescript
// ❌ BAD - Exposes internal details
return c.json({ error: `Database connection failed: ${dbError.stack}` }, 500);

// ✅ GOOD - Generic message, log details server-side
console.error('Database error:', dbError);
return c.json({ error: 'Unknown error occurred' }, 500);
```

#### 2. Use Appropriate Status Codes

```typescript
// ❌ BAD - Returns 401 revealing user exists
if (!user) {
  return c.json({ error: 'User not found' }, 401);
}

// ✅ GOOD - Returns 400 to prevent enumeration
if (!user || !validPassword) {
  return c.json({ error: 'Incorrect email or password' }, 400);
}
```

#### 3. Log Errors with Context

```typescript
try {
  const output = await callReplicate(apiKey, model, input);
  return c.json({ url: output });
} catch (error: unknown) {
  const msg = error instanceof Error ? error.message : 'Unknown error';

  console.error('[Image Generate] Replicate error:', {
    model,
    error: msg,
    userId: user?.id,
    timestamp: new Date().toISOString()
  });

  return c.json({ error: msg }, 500);
}
```

#### 4. Validate Input Early

```typescript
if (!email || !password || typeof email !== 'string' || typeof password !== 'string') {
  return c.json({ error: 'Invalid input' }, 400);
}
```

