## Retry Strategies

### Exponential Backoff

For transient errors (429, 500, 503), implement exponential backoff:

```typescript
async function retryWithBackoff<T>(
  fn: () => Promise<T>,
  maxRetries: number = 3,
  baseDelay: number = 1000
): Promise<T> {
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      const shouldRetry = error instanceof ApiError &&
                          [429, 500, 503].includes(error.status);

      if (!shouldRetry || attempt === maxRetries - 1) {
        throw error;
      }

      const delay = baseDelay * Math.pow(2, attempt);
      const jitter = Math.random() * 1000;
      await sleep(delay + jitter);
    }
  }
  throw new Error('Max retries exceeded');
}
```

### Rate Limit Specific Retry

For rate limit errors, respect the `Retry-After` header:

```typescript
async function retryWithRateLimit<T>(fn: () => Promise<T>): Promise<T> {
  try {
    return await fn();
  } catch (error) {
    if (error instanceof ApiError && error.status === 429) {
      const retryAfter = parseRetryAfter(error);
      if (retryAfter) {
        await sleep(retryAfter * 1000);
        return await fn();
      }
    }
    throw error;
  }
}
```

### Circuit Breaker Pattern

For provider failures, implement circuit breaker:

```typescript
class CircuitBreaker {
  private failures = 0;
  private lastFailure: number = 0;
  private readonly threshold = 5;
  private readonly timeout = 60000;

  async execute<T>(fn: () => Promise<T>): Promise<T> {
    if (this.isOpen()) {
      throw new Error('Circuit breaker is open');
    }

    try {
      const result = await fn();
      this.onSuccess();
      return result;
    } catch (error) {
      this.onFailure();
      throw error;
    }
  }

  private isOpen(): boolean {
    return this.failures >= this.threshold &&
           (Date.now() - this.lastFailure) < this.timeout;
  }

  private onSuccess(): void {
    this.failures = 0;
  }

  private onFailure(): void {
    this.failures++;
    this.lastFailure = Date.now();
  }
}
```

